-- What a user sees of clinic A, by table, after setting A's level (as postgres) in a rolled-back subtransaction:
-- "<tables with at least one visible tenant-A row, sorted>|storage:<visible tenant-A objects>". The table list comes
-- from the live catalogue (every public table with a tenant_id, plus tenants by id), so a new table is covered.
create function pg_temp.lock_view(p_level text, p_user uuid) returns text
language plpgsql
as $fn$
declare
    v_seen text[] := '{}';
    v_rel record;
    v_n bigint;
    v_out text;
begin
    begin
        if p_level = 'locked' then
            execute 'update public.tenant_subscriptions set access_ends_at = now() - interval ''1 day'' where tenant_id = ''a5a00000-0000-4000-8000-00000000000a''';
        elsif p_level = 'onboarding' then
            execute 'update public.tenant_subscriptions set status = ''incomplete'', comp_until = null where tenant_id = ''a5a00000-0000-4000-8000-00000000000a''';
        end if;
        perform set_config('request.jwt.claim.sub', '', true);
        perform set_config('request.jwt.claims', json_build_object('sub', p_user, 'role', 'authenticated')::text, true);
        perform set_config('request.headers', '', true);
        set local role authenticated;
        for v_rel in
            select c.relname::text as name
              from pg_class c join pg_namespace n on n.oid = c.relnamespace
             where n.nspname = 'public' and c.relkind in ('r', 'p')
               and exists (select 1 from pg_attribute a where a.attrelid = c.oid and a.attname = 'tenant_id' and not a.attisdropped)
             order by 1
        loop
            begin
                execute format('select count(*) from public.%I where tenant_id = %L', v_rel.name, 'a5a00000-0000-4000-8000-00000000000a') into v_n;
            exception
                when insufficient_privilege then
                    v_n := 0;
            end;
            if v_n > 0 then
                v_seen := v_seen || v_rel.name;
            end if;
        end loop;
        select count(*) into v_n from public.tenants where id = 'a5a00000-0000-4000-8000-00000000000a';
        if v_n > 0 then
            v_seen := v_seen || 'tenants'::text;
        end if;
        select count(*) into v_n from storage.objects where name like '%a5a00000-0000-4000-8000-00000000000a%';
        v_out := coalesce((select string_agg(x, ',' order by x) from unnest(v_seen) x), '') || '|storage:' || v_n;
        raise exception 'lock view sentinel' using errcode = 'AZ997';
    exception
        when sqlstate 'AZ997' then
            null;
    end;
    return v_out;
end;
$fn$;

-- One upload per storage class of clinic A as the user, A at p_level: 'ok' or 'denied' (42501), in class order.
create function pg_temp.lock_uploads(p_level text, p_user uuid) returns text
language plpgsql
as $fn$
declare
    v_obj record;
    v_res text[] := '{}';
begin
    for v_obj in select * from (values ('prescriptions', 'a5a00000-0000-4000-8000-00000000000a/a5a00000-0000-4000-8000-000000001002/rx_v2.pdf'), ('prescriptions', 'a5a00000-0000-4000-8000-00000000000a/receipts/inv_a5a00000-0000-4000-8000-000000002039.pdf'), ('clinic-records', 'tenants/a5a00000-0000-4000-8000-00000000000a/patients/a5a00000-0000-4000-8000-000000001001/labs/a5a00000-0000-4000-8000-00000000203e.pdf'), ('clinic-records', 'tenants/a5a00000-0000-4000-8000-00000000000a/referrals/a5a00000-0000-4000-8000-00000000203a/referral_letter.pdf'), ('clinic-records', 'a5a00000-0000-4000-8000-00000000000a/legacy/file2.pdf')) o(bucket, name) loop
        begin
            if p_level = 'locked' then
                execute 'update public.tenant_subscriptions set access_ends_at = now() - interval ''1 day'' where tenant_id = ''a5a00000-0000-4000-8000-00000000000a''';
            else
                execute 'update public.tenant_subscriptions set status = ''incomplete'', comp_until = null where tenant_id = ''a5a00000-0000-4000-8000-00000000000a''';
            end if;
            perform set_config('request.jwt.claims', json_build_object('sub', p_user, 'role', 'authenticated')::text, true);
            perform set_config('request.headers', '', true);
            set local role authenticated;
            insert into storage.objects (bucket_id, name) values (v_obj.bucket, v_obj.name);
            v_res := v_res || 'ok'::text;
            raise exception 'upload sentinel' using errcode = 'AZ996';
        exception
            when sqlstate 'AZ996' then
                null;
            when insufficient_privilege then
                v_res := v_res || 'denied'::text;
        end;
    end loop;
    return array_to_string(v_res, ',');
end;
$fn$;

